#!/usr/bin/env node
// Generates src/design/tokens.css from src/design/tokens.json (the canonical numeric
// source copied unchanged from the handoff). Run with --check in CI to fail when the
// generated file is stale. Do not hand-edit tokens.css.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const source = path.join(root, "src", "design", "tokens.json");
const target = path.join(root, "src", "design", "tokens.css");
const tokens = JSON.parse(fs.readFileSync(source, "utf8"));

const kebab = (s) => s.replace(/[A-Z]/g, (m) => `-${m.toLowerCase()}`);
const px = (n) => `${n}px`;
const lines = [];
const add = (name, value) => lines.push(`  --${name}: ${value};`);

for (const [k, v] of Object.entries(tokens.color)) add(`color-${kebab(k)}`, v);
add("font-family", `"${tokens.font.family}", ${tokens.font.fallback}`);
for (const w of tokens.font.weights) add(`font-weight-${w}`, String(w));
for (const [k, [size, lh]] of Object.entries(tokens.type)) {
  add(`type-${kebab(k)}-size`, px(size));
  add(`type-${kebab(k)}-line`, px(lh));
}
tokens.space.forEach((v, i) => add(`space-${i + 1}`, px(v)));
for (const [k, v] of Object.entries(tokens.radius)) add(`radius-${kebab(k)}`, px(v));
for (const [k, v] of Object.entries(tokens.layout)) add(`layout-${kebab(k)}`, px(v));
for (const [k, v] of Object.entries(tokens.control)) add(`control-${kebab(k)}`, px(v));
add("motion-duration", `${tokens.motion.durationMs}ms`);
add("shadow-popover", tokens.shadow.popover);

const css = `/* GENERATED by scripts/design/generate-tokens.mjs from tokens.json v${tokens.version}. Do not edit. */
:root {
${lines.join("\n")}
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --motion-duration: ${tokens.motion.reducedMotionDurationMs}ms;
  }
}
`;

if (process.argv.includes("--check")) {
  const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : "";
  if (current.replace(/\r\n/g, "\n") !== css) {
    console.error("tokens.css is out of date. Run: npm run design:tokens");
    process.exit(1);
  }
  console.log("tokens.css is up to date");
} else {
  fs.writeFileSync(target, css);
  console.log(`wrote ${path.relative(root, target)} (${lines.length} variables)`);
}
